    ups.forEach((u, i) => { const g = GAMES.find(x => x.id === u[1]); if (g && g.released && daysSince(g.released) <= NEW_DAYS && g.released > best) { best = g.released; lead = i; } });
    return lead > 0 ? [ups[lead], ...ups.slice(0, lead), ...ups.slice(lead + 1)] : ups;
